<?php
declare(strict_types=1);require_once __DIR__.'/../vendor/autoload.php';require_once __DIR__.'/config.php';use Dompdf\Dompdf;use Dompdf\Options;
function generateOfferPdf(array $c,array $ps,float $total):array{$dir=__DIR__.'/offers';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Folderul offers nu poate fi creat.');$no='OP-'.date('Ymd-His').'-'.random_int(100,999);$file=$dir.'/'.$no.'.pdf';$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$rows='';foreach($ps as $p){$q=(int)$p['quantity'];$pr=(float)$p['price'];$rows.='<tr><td>'.$e($p['name']??'Produs').'<br><small>Cod: '.$e($p['code']??'').'</small></td><td>'.$q.'</td><td>'.number_format($pr,2,'.',' ').' MDL</td><td>'.number_format($q*$pr,2,'.',' ').' MDL</td></tr>';}$html='<meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:11px}h1{font-size:22px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:7px}th{background:#eee}.box{border:1px solid #ccc;padding:10px;margin:12px 0}.total{text-align:right;font-size:15px;font-weight:bold;margin-top:12px}</style><h1>OfficePlus</h1><b>GRECU OFFICE GROUP SRL</b><br>'.OFFICEPLUS_ADDRESS.'<br>Tel: '.OFFICEPLUS_PHONE.' | '.OFFICEPLUS_EMAIL.'<hr><h2>OFERTĂ COMERCIALĂ</h2><b>Nr.:</b> '.$e($no).' &nbsp; <b>Data:</b> '.date('d.m.Y H:i').'<div class="box"><b>Client:</b> '.$e($c['name']??'').'<br><b>Telefon:</b> '.$e($c['phone']??'').'<br><b>Email:</b> '.$e($c['email']??'').'<br><b>Companie:</b> '.$e($c['company']??'').'<br><b>Localitate:</b> '.$e($c['city']??'').'<br><b>Adresă:</b> '.$e($c['address']??'').'</div><table><tr><th>Produs</th><th>Cant.</th><th>Preț</th><th>Total</th></tr>'.$rows.'</table><div class="total">TOTAL: '.number_format($total,2,'.',' ').' MDL</div><div class="box">Livrare: '.$e($c['delivery']??'pickup').' &nbsp; Plată: '.$e($c['payment']??'transfer').'</div>'; $o=new Options();$o->set('defaultFont','DejaVu Sans');$pdf=new Dompdf($o);$pdf->setPaper('A4','portrait');$pdf->loadHtml($html,'UTF-8');$pdf->render();file_put_contents($file,$pdf->output());return ['success'=>true,'offer_number'=>$no,'pdf_url'=>offerBaseUrl().'/offers/'.rawurlencode($no).'.pdf','file'=>$file];}
// RO: adresa PDF-ului se ia din locul REAL unde e instalat widgetul (de ex. /OfficePlus_Chatbot/api),
//     nu din radacina site-ului: altfel clientul primeste un link 404 (16.09.2026).
function offerBaseUrl():string{$d=str_replace('\\','/',dirname((string)($_SERVER['SCRIPT_NAME']??'/OfficePlus_Chatbot/api/x.php')));if($d===''||$d==='.'||$d==='/')$d='/OfficePlus_Chatbot/api';return rtrim(OFFICEPLUS_SITE,'/').'/'.trim($d,'/');}
